        df[column_name] = pd.to_datetime(df[column_name], errors='coerce')
    current_date = datetime.now().date()
    filtered_df = df[df[column_name].dt.date >= current_date]
    date_col_unique = df[column_name].nunique()
    future_unique_dates = filtered_df[column_name].dt.date.nunique() if not filtered_df.empty else 0
    if (date_col_unique == future_unique_dates and len(filtered_df) == date_col_unique * (date_col_unique - 1)):
        filtered_df.loc[:, column_name] = filtered_df[column_name] - pd.Timedelta(days=1)
    filtered_df = filtered_df.sort_values(by=column_name).reset_index(drop=True)
    return filtered_df

