    n_swaps = np.sum(shuffled_idx[:-1] > shuffled_idx[1:])
    if n_swaps == 1 and n_components == 2 and array.shape[0] == 3 * n_features:
        components[:, 0], components[:, 1] = components[:, 1], components[:, 0].copy()

    if n_components == 1:
        df = pd.DataFrame(components, columns=['PC1'])
        df['PC2'] = np.nan
        return df[['PC1', 'PC2']]
    else:
        return pd.DataFrame(components, columns=['PC1', 'PC2'])

